+}
+
+export interface HeavyRainEventCandidate {
+  trackId: string;
+  startsAt: string;
+  endsAt: string;
+  maxLevel: HeavyRainLevel;
+  start: { latitude: number; longitude: number };
+  end: { latitude: number; longitude: number };
