import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { JAPAN_PREFECTURES } from "../lib/weather/rain/japanPrefectures";
import { n03PrefectureArchiveUrl, n03PrefectureGeoJsonName } from "../lib/weather/rain/n03Dataset";
import { parseN03FeatureCollection, type N03FeatureCollection } from "../lib/weather/rain/n03AdministrativeAreas";
import type { N03PrefectureIndexEntry } from "../lib/weather/rain/n03Prefectures";

const root = mkdtempSync(join(tmpdir(), "n03-national-"));
const index: N03PrefectureIndexEntry[] = [];
for (const prefecture of JAPAN_PREFECTURES) {
  const zip = join(root, prefecture.code + ".zip");
  const dir = join(root, prefecture.code);
  execFileSync("curl", ["--fail","--location","--retry","3",n03PrefectureArchiveUrl(prefecture.code),"-o",zip], { stdio: "ignore" });
  execFileSync("mkdir", ["-p",dir]);
  execFileSync("unzip", ["-q",zip,"-d",dir]);
  const file = join(dir, n03PrefectureGeoJsonName(prefecture.code));
  const collection = JSON.parse(readFileSync(file,"utf8")) as N03FeatureCollection;
  const areas = parseN03FeatureCollection(collection).filter((area) => area.prefecture === prefecture.name);
  if (!areas.length) throw new Error(`No N03 areas for ${prefecture.code} ${prefecture.name}`);
  let west=Infinity,south=Infinity,east=-Infinity,north=-Infinity;
  for (const area of areas) {
    const polygons = area.geometry.type === "Polygon" ? [area.geometry.coordinates as number[][][]] : area.geometry.coordinates as number[][][][];
    for (const polygon of polygons) for (const [lon,lat] of polygon[0] ?? []) {
      west=Math.min(west,lon); south=Math.min(south,lat); east=Math.max(east,lon); north=Math.max(north,lat);
    }
  }
  index.push({ code: prefecture.code, name: prefecture.name, bbox:[west,south,east,north] });
}
if (index.length !== 47) throw new Error(`Expected 47 prefectures, got ${index.length}`);
console.log(JSON.stringify({ prefectures:index.length, index }));

#!/usr/bin/env python3
"""Offline N03 oversized-polygon geometric clipping proof. Requires shapely>=2,<3.
No Storage calls; produces aggregate diagnostics only, never geometry output.
"""
import json, math, sys, shutil
from pathlib import Path
from shapely.geometry import Polygon, box
from shapely.ops import unary_union

LIMIT=1572864
def polygon_parts(area):
    g=area["geometry"]
    return [g["coordinates"]] if g["type"]=="Polygon" else g["coordinates"]

def encoded_bytes(coords):
    return len(json.dumps({"type":"Polygon","coordinates":coords},separators=(",",":"),ensure_ascii=False).encode())

def components(geom):
    if geom.is_empty: return []
    if geom.geom_type=="Polygon": return [geom]
    if hasattr(geom,"geoms"):
        return [p for sub in geom.geoms for p in components(sub)]
    return []

def main(root, output=None):
    if output:
        output.mkdir(parents=True, exist_ok=True)
        for pref in range(1,48):
            shutil.copyfile(root/f"{pref:02}.areas.json", output/f"{pref:02}.areas.json")
    oversized=[]
    for pref in range(1,48):
        for area in json.loads((root/f"{pref:02}.areas.json").read_text()):
            for idx,rings in enumerate(polygon_parts(area)):
                if encoded_bytes(rings)>LIMIT:
                    oversized.append((f"{pref:02}",area["code"],idx,rings))
    results=[]
    replacements={}
    for pref,code,idx,rings in oversized:
        poly=Polygon(rings[0],rings[1:])
        if not poly.is_valid:
            results.append({"pref":pref,"code":code,"polygonOrder":idx,"status":"INVALID_ORIGINAL","reason":"cannot claim equivalence without repair"})
            continue
        minx,miny,maxx,maxy=poly.bounds
        best=None
        for divisions in (2,4,8,16,32):
            dx=(maxx-minx)/divisions;dy=(maxy-miny)/divisions
            fragments=[]
            for ix in range(divisions):
                for iy in range(divisions):
                    cut=poly.intersection(box(minx+ix*dx,miny+iy*dy,minx+(ix+1)*dx,miny+(iy+1)*dy))
                    fragments.extend(components(cut))
            sizes=[encoded_bytes([list(p.exterior.coords)]+[list(r.coords) for r in p.interiors]) for p in fragments]
            if not sizes: raise RuntimeError(f"Clipping removed polygon {code}")
            union=unary_union(fragments)
            symmetric=poly.symmetric_difference(union).area
            tolerance=max(poly.area*1e-9,1e-13)
            if symmetric>tolerance: raise RuntimeError(f"Area mismatch {code} {symmetric}")
            best={"divisions":divisions,"fragments":len(fragments),"maxFragmentBytes":max(sizes),"totalFragmentBytes":sum(sizes),"symmetricDifferenceArea":symmetric}
            if max(sizes)<LIMIT: break
        results.append({"pref":pref,"code":code,"polygonOrder":idx,"status":"CLIPPED" if best["maxFragmentBytes"]<LIMIT else "STILL_OVERSIZED",**best})
        if output and best["maxFragmentBytes"]<LIMIT:
            replacements[(pref,code,idx)]=[[list(p.exterior.coords)]+[list(r.coords) for r in p.interiors] for p in fragments]
    if output:
        for pref in sorted({p for p,_,_ in replacements}):
            source=json.loads((root/f"{pref}.areas.json").read_text())
            for area in source:
                original=polygon_parts(area)
                rewritten=[]
                for i,rings in enumerate(original):
                    rewritten.extend(replacements.get((pref,area["code"],i),[rings]))
                area["geometry"]={"type":"MultiPolygon","coordinates":rewritten}
            (output/f"{pref}.areas.json").write_text(json.dumps(source,separators=(",",":"),ensure_ascii=False))
    print(json.dumps({"mode":"N03_OVERSIZED_SHAPELY_RECTANGLE_CLIP_PROOF","thresholdBytes":LIMIT,"oversizedCount":len(oversized),"results":results,"limitations":["Polygon area equivalence is not proof of JS rain-boundary predicate equivalence","Polygon boundaries may acquire tile edges and change touching-only matches","Offline proof only: no production data format or Storage writes"],"decision":"EXPERIMENT_ONLY_NOT_ADOPTED"}))
    if any(x["status"]!="CLIPPED" for x in results): sys.exit(1)
if __name__=="__main__":
    if len(sys.argv) not in (2,3): sys.exit("Usage: python scripts/n03-oversized-clip-proof.py <prepared-dir> [experimental-output-dir]")
    main(Path(sys.argv[1]),Path(sys.argv[2]) if len(sys.argv)==3 else None)

