+  let strongPixels = 0;
+  let tileCount = 0;
+  let deferred = false;
+  const polygons: HeavyRainPolygon[] = [];
+  const processedTiles: Array<{ x: number; y: number }> = [];
+  const remainingTiles: Array<{ x: number; y: number }> = [];
