+    trackedRegions: [...timelineTileFrames.entries()].map(([tile, validTimes]) => ({ tile, firstValidTime: validTimes[0], lastValidTime: validTimes[validTimes.length - 1], frameCount: validTimes.length }))
+  }, null, 2));
+  
+}
+
+main().catch((error) => {
+  console.error(error);
+  process.exit(1);
+});

