+    const outstanding = [...queue, ...active.flatMap(a => a.jobs)];
+    const oldestCreated = outstanding.reduce((oldest, job) => Math.min(oldest, job.created), Infinity);
+    const byRegion = Object.fromEntries(regions.map(region => {
