    peakRssMiB = Math.max(peakRssMiB, active.reduce((s, a) => s + a.rss, 0));
    if (now === horizon) { snapshot(options.cycles); break; }
    const wake = queue.filter(j => eligible(j) > now).map(eligible);
    const next = Math.min(horizon, cycle < options.cycles ? cycle * period : horizon, ...active.map(a => a.end), ...(queue.length && !boost && active.length < options.globalCap ? [oldest + (options.oldestThresholdMs ?? 60_000)] : []), ...(active.length < options.globalCap ? wake : []));
    if (next <= now) throw new Error("Replay failed to advance"); now = next;
  }
  function snapshot(cycleNumber: number) {
    const outstanding = [...queue, ...active.flatMap(a => a.jobs)];
    const oldestCreated = outstanding.reduce((oldest, job) => Math.min(oldest, job.created), Infinity);
    const byRegion = Object.fromEntries(regions.map(region => {
      const pending = outstanding.filter(job => job.region === region);
      const oldest = pending.reduce((time, job) => Math.min(time, job.created), Infinity);
      return [region, { remaining: pending.length, oldestAgeSeconds: pending.length ? (now - oldest) / 1000 : 0 }];
    }));
    rows.push({ cycle: cycleNumber, submitted, processed: completed.size, remaining: outstanding.length, oldestAgeSeconds: outstanding.length ? (now - oldestCreated) / 1000 : 0, invocationCount, byRegion });
  }
  return { mode: "MEASURED_SERVICE_SCHEDULER_REPLAY", policy: options.policy, globalCap: options.globalCap, staggerMs: options.staggerMs ?? 3000, serviceMultiplier: options.serviceMultiplier ?? 1.5, arrivals: options.arrivals, cycles: options.cycles, horizonSeconds: horizon / 1000, submitted, processed: completed.size, remaining: submitted - completed.size, invocationCount, peakConcurrency, backlogThreshold: options.backlogThreshold, oldestThresholdMs: options.oldestThresholdMs, peakOutstanding: peakQueue, summedWorkerPeakRssMiB: peakRssMiB, rows, capacityAccepted: false, limitations: ["Virtual 5-minute arrivals, measured worker service profiles", "No real continuously arriving Production queue/DB/JMA", "Sum of process peaks is a conservative proxy, not simultaneous measured RSS", "Arrival demand and 1.5 service multiplier are scenario assumptions", "Only four representative region workloads, not nationwide coverage evidence"] };
}

