import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createClient } from "@supabase/supabase-js";
import { N03_DATASET_DATE } from "../lib/weather/rain/n03Dataset";
import {
  NATIONAL_RAIN_N03_BUCKET,
  nationalRainN03ObjectPath,
} from "../lib/weather/rain/n03PreparedStorageLoader";

async function main() {
  const url = process.env.SUPABASE_URL;
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !serviceRoleKey) throw new Error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");

  const manifestPath = resolve(process.argv[2] ?? `tmp/n03-prepared/${N03_DATASET_DATE}/manifest.json`);
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8")) as {
    dataset: string;
    files: { code: string; bytes: number; sha256: string }[];
  };
  if (manifest.dataset !== `N03-${N03_DATASET_DATE}`) throw new Error("Unexpected N03 dataset");
  if (manifest.files.length !== 47) throw new Error(`Expected 47 prefectures, got ${manifest.files.length}`);

  const supabase = createClient(url, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  for (const file of manifest.files) {
    const path = nationalRainN03ObjectPath(file.code);
    const { data, error } = await supabase.storage.from(NATIONAL_RAIN_N03_BUCKET).download(path);
    if (error || !data) throw new Error(`Missing Storage object: ${path}: ${error?.message ?? "missing data"}`);
    const body = Buffer.from(await data.arrayBuffer());
    if (body.byteLength !== file.bytes) throw new Error(`Storage size mismatch: ${path}`);
    const sha256 = createHash("sha256").update(body).digest("hex");
    if (sha256 !== file.sha256) throw new Error(`Storage SHA-256 mismatch: ${path}`);
    console.log(`verified ${path} (${body.byteLength} bytes)`);
  }

  console.log(`verified 47 immutable N03 objects for N03-${N03_DATASET_DATE}`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

-- PR #59 proof state only. DO NOT apply to Production until explicitly reviewed.
-- Records whether a JMA nationwide forecast basetime has been completely scanned.
-- Separate from watch_targets, Push, and user-facing notification state.

create table if not exists public.national_rain_scan_cycles (
  basetime timestamptz primary key,
  status text not null check (status in ('INCOMPLETE','COMPLETED')),
  required_frames integer not null default 0 check (required_frames >= 0),
  usable_frames integer not null default 0 check (usable_frames >= 0 and usable_frames <= required_frames),
  completed_at timestamptz,
  updated_at timestamptz not null default now()
);

comment on table public.national_rain_scan_cycles is
  'Proof-only nationwide rain scan cycle state. A basetime is COMPLETED only after every required forecast frame is usable and queue writes succeed.';

create index if not exists national_rain_scan_cycles_completed_idx
  on public.national_rain_scan_cycles (status, basetime desc);

revoke all on table public.national_rain_scan_cycles from public, anon, authenticated;
grant select, insert, update on table public.national_rain_scan_cycles to service_role;
